import {compile} from './math.js';
import {levels,simulate,fmt,CONNECT} from './levels.js';
const $=id=>document.getElementById(id), canvas=$('board'),ctx=canvas.getContext('2d');
const COLORS={mint:'#79efd0',gold:'#ffc875',pink:'#e3889b',white:'#e9f2f7',grid:'#233040'};
let mode='challenge',level=levels[1],attempts=0,previous=null,run=null,compiled=null,param={a:1,h:0,k:0},comparisons=[],hintStep=0,filter='Todos',progress={},drafts={},sandboxDraft='a*(x-h)^2+k',hover=null;
let world={xmin:-1.1,xmax:11.1,ymin:-2,ymax:9.4},size={w:900,h:460},raf=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const examples=[['Recta','a*x+k','a es la pendiente; k es la altura en x=0.'],['Parábola','a*(x-h)^2+k','(h,k) es el vértice. a cambia la apertura y su orientación. No son b y c de ax²+bx+c.'],['Exponencial','2^(a*(x-h))+k','Base 2: cada unidad duplica el valor. a cambia la rapidez; h y k desplazan la curva.'],['Onda','a*sin(x-h)+k','a controla la amplitud, h el desplazamiento horizontal y k la altura central. Los ángulos están en radianes.'],['Raíz','a*sqrt(x-h)+k','El dominio empieza en x=h. La raíz crece cada vez más despacio.'],['Valor absoluto','a*abs(x-h)+k','(h,k) ubica la esquina de la V. El signo de a decide su orientación.'],['Logaritmo','a*ln(x-h)+k','Necesitás x>h. Hay una asíntota vertical en x=h.'],['Racional','a/(x-h)+k','x=h queda fuera del dominio. y=k es la asíntota horizontal.']];
function px(x){return 36+(x-world.xmin)/(world.xmax-world.xmin)*(size.w-60)}function py(y){return 20+(world.ymax-y)/(world.ymax-world.ymin)*(size.h-48)}
function unpx(x){return world.xmin+(x-36)/(size.w-60)*(world.xmax-world.xmin)}function unpy(y){return world.ymax-(y-20)/(size.h-48)*(world.ymax-world.ymin)}
function setFeedback(message,type='neutral'){$('feedback').textContent=message;$('feedback').className='feedback '+type}
function path(points,color,width=2,alpha=1,dashed=false){ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dashed?[5,5]:[]);ctx.beginPath();let first=true;for(const p of points){if(!Number.isFinite(p.y)||p.y<world.ymin-1||p.y>world.ymax+1){first=true;continue}if(first){ctx.moveTo(px(p.x),py(p.y));first=false}else ctx.lineTo(px(p.x),py(p.y))}ctx.stroke();ctx.restore()}
function sample(fn,params=param){const arr=[];let last=null;for(let i=0;i<=1200;i++){let x=world.xmin+(world.xmax-world.xmin)*i/1200,y=fn(x,params);if(last!==null&&Math.abs(y-last)>1)arr.push({x,y:NaN});arr.push({x,y});last=y}return arr}
function grid(){ctx.clearRect(0,0,size.w,size.h);ctx.fillStyle='#121923';ctx.fillRect(0,0,size.w,size.h);ctx.font='11px ui-monospace, monospace';const step=world.xmax-world.xmin>15?2:1;
 for(let x=Math.ceil(world.xmin);x<=world.xmax;x++){ctx.strokeStyle=x===0?'#4a5d6e':COLORS.grid;ctx.lineWidth=x===0?1.2:.65;ctx.beginPath();ctx.moveTo(px(x),20);ctx.lineTo(px(x),size.h-28);ctx.stroke();if(x%step===0){ctx.fillStyle='#95a7ba';ctx.textAlign='center';ctx.fillText(x,px(x),Math.min(size.h-10,Math.max(34,py(0)+18)))}}
 for(let y=Math.ceil(world.ymin);y<=world.ymax;y++){ctx.strokeStyle=y===0?'#4a5d6e':COLORS.grid;ctx.lineWidth=y===0?1.2:.65;ctx.beginPath();ctx.moveTo(36,py(y));ctx.lineTo(size.w-24,py(y));ctx.stroke();if(y%step===0&&y!==0){ctx.fillStyle='#95a7ba';ctx.textAlign='right';ctx.fillText(y,Math.max(28,px(0)-10),py(y)+4)}}
 ctx.fillStyle='#bac6d3';ctx.font='italic 13px Georgia';ctx.textAlign='right';ctx.fillText('x',size.w-12,py(0)-8);ctx.fillText('y',px(0)+17,17);
}
function platform(p,color,label){const x=px(p.x),y=py(p.y),unit=(size.w-60)/(world.xmax-world.xmin);ctx.save();ctx.fillStyle=color+'12';ctx.fillRect(x-unit*.4,y,unit*.8,size.h-y);ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-unit*.42,y);ctx.lineTo(x+unit*.42,y);ctx.stroke();ctx.setLineDash([3,4]);ctx.lineWidth=1;ctx.strokeStyle=color+'60';ctx.strokeRect(x-unit*.27,y-Math.abs(py(p.y+CONNECT)-py(p.y)),unit*.54,Math.abs(py(p.y+CONNECT)-py(p.y))*2);ctx.setLineDash([]);ctx.fillStyle=color;ctx.font='bold 10px ui-monospace,monospace';ctx.textAlign=p.x===0?'left':'right';ctx.fillText(label,x+(p.x===0?10:-10),y+24);ctx.restore()}
function map(reached=new Set()){for(const o of level.obstacles){const x=px(o.x),y=py(o.y+o.h),w=px(o.x+o.w)-x,h=py(o.y)-y;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.fillStyle='#65314355';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#9f566745';ctx.lineWidth=1;for(let a=x-h;a<x+w+h;a+=13){ctx.beginPath();ctx.moveTo(a,y+h);ctx.lineTo(a+h,y);ctx.stroke()}ctx.restore();ctx.strokeStyle='#b56b80';ctx.lineWidth=1;ctx.strokeRect(x,y,w,h)}
 platform(level.start,COLORS.mint,'START');platform(level.end,COLORS.white,'FINISH');
 level.coins.forEach((c,i)=>{ctx.save();ctx.translate(px(c.x),py(c.y));ctx.rotate(Math.PI/4);ctx.fillStyle=reached.has(i)?'#ffc87522':COLORS.gold;ctx.strokeStyle=reached.has(i)?'#ffc87566':COLORS.gold;ctx.lineWidth=1.5;ctx.shadowColor=COLORS.gold;ctx.shadowBlur=reached.has(i)?0:12;ctx.fillRect(-5,-5,10,10);ctx.strokeRect(-5,-5,10,10);ctx.restore()});
}
function player(x,y,angle=0,alpha=1){ctx.save();ctx.globalAlpha=alpha;ctx.translate(px(x),py(y)-7);ctx.rotate(angle);ctx.fillStyle=COLORS.mint;ctx.shadowColor=COLORS.mint;ctx.shadowBlur=15;ctx.fillRect(-6,-6,12,12);ctx.shadowBlur=0;ctx.fillStyle='#12362e';ctx.fillRect(-3,-2,2,2);ctx.fillRect(2,-2,2,2);ctx.restore()}
function draw(t=performance.now()){grid();if(mode==='sandbox'){
 if(!$('axesOnly').checked){ctx.strokeStyle='#79efd030';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(36,py(0));ctx.lineTo(size.w-24,py(0));ctx.stroke()}
 comparisons.forEach(c=>path(sample(c.fn,c.params),c.color,1.8,.7));if(compiled){path(sample(compiled.fn),COLORS.mint,2.5);if(run){const elapsed=(t-run.time)/3000;const x=world.xmin+(world.xmax-world.xmin)*Math.min(1,elapsed),y=compiled.fn(x,param);if(Number.isFinite(y)&&y>=world.ymin&&y<=world.ymax)player(x,y,elapsed*8);if(elapsed>=1)finishSandbox()}}
 }else{
 const collected=new Set();let point=level.start,fraction=0;
 if(run){const elapsed=t-run.time;fraction=Math.min(1,elapsed/run.duration);run.endPhase=Math.max(0,(elapsed-run.duration)/450);if(run.result.kind==='start'){point={x:fraction*.8,y:level.start.y+Math.sin(fraction*Math.PI)*.7-fraction*fraction*5}}else{const pts=run.result.points;const idx=Math.max(0,Math.min(pts.length-1,Math.floor(fraction*(pts.length-1))));point=pts[idx]||level.start;for(const id of run.result.coins){if(level.coins[id].x<=point.x+.12)collected.add(id)}}}
 else if(previous){previous.result.coins.forEach(c=>collected.add(c));point=previous.result.kind==='finish'?level.end:level.start}
 if(run&&fraction>=1&&['miss','bounds','domain'].includes(run.result.kind)){point={x:point.x+run.endPhase*.3,y:point.y-run.endPhase*run.endPhase*3}}
 map(collected);if(previous&&$('ghost').checked&&!run)path(previous.result.points,COLORS.mint,2,.35,true);
 if(run&&run.result.kind!=='start'){const pts=run.result.points,idx=Math.max(1,Math.floor(fraction*pts.length));path(pts.slice(0,idx),COLORS.mint,2.8,1)}
 player(point.x,point.y,run?fraction*12:0,run?.result.kind==='start'?1-fraction*.7:1);
 if(previous&&!run&&previous.result.kind!=='finish'&&previous.result.kind!=='start'){ctx.strokeStyle=COLORS.pink;ctx.lineWidth=2;const x=px(previous.result.x),y=py(previous.result.y);ctx.beginPath();ctx.moveTo(x-6,y-6);ctx.lineTo(x+6,y+6);ctx.moveTo(x+6,y-6);ctx.lineTo(x-6,y+6);ctx.stroke()}
 $('coinsCount').textContent=`${collected.size} / ${level.coins.length}`;if(run&&fraction>=1&&(run.result.kind==='finish'||run.endPhase>=1))finishRun();
 }
 if(hover){ctx.save();ctx.setLineDash([3,5]);ctx.strokeStyle='#9bb2c64d';ctx.beginPath();ctx.moveTo(hover.x,20);ctx.lineTo(hover.x,size.h-28);ctx.moveTo(36,hover.y);ctx.lineTo(size.w-24,hover.y);ctx.stroke();ctx.restore()}
 if(run)raf=requestAnimationFrame(draw);
}
function render(){if(!run)draw()}
function resize(){let r=canvas.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);size={w:r.width,h:r.height};canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);render()}
new ResizeObserver(resize).observe(canvas);
function cancelRun(){cancelAnimationFrame(raf);run=null;$('tryButton').disabled=false;$('expression').disabled=false}
function finishSandbox(){run=null;$('tryButton').disabled=false;setFeedback('Explorá otra expresión, mové los parámetros o guardá esta curva para compararla.');requestAnimationFrame(()=>render())}
function finishRun(){const result=run.result;previous={result,expression:run.expression};run=null;$('tryButton').disabled=false;$('expression').disabled=false;setFeedback(result.message,result.kind==='finish'?'success':'error');$('visibilityLabel').textContent='Último intento: '+previous.expression;if(result.kind==='finish'){
 const old=progress[level.id];progress[level.id]={coins:Math.max(old?.coins||0,result.coins.length)};$('resultBadge').hidden=false;$('resultBadge').textContent=result.coins.length===level.coins.length?'✦ Trayectoria perfecta':'✓ Desafío completado';}
 requestAnimationFrame(()=>render());
}
function startTry(e){e?.preventDefault();if(run)return;if(mode==='sandbox'){updateSandbox();if(!compiled)return;run={time:performance.now()};$('tryButton').disabled=true;setFeedback('Recorriendo la curva. Los tramos fuera del dominio no se dibujan.');raf=requestAnimationFrame(draw);return}
 let c;try{c=compile($('expression').value);if(containsParams(c.ast))throw Error('En los desafíos, reemplazá a, h y k por números.')}catch(err){setFeedback(err.message,'error');return}
 const result=simulate(c,level);attempts++;$('attemptLabel').textContent='INTENTO '+String(attempts).padStart(2,'0');$('resultBadge').hidden=true;$('mapCaption').hidden=true;$('tryButton').disabled=true;$('expression').disabled=true;setFeedback('Probando tu trayectoria…');run={result,expression:$('expression').value,time:performance.now(),duration:reduced?250:result.kind==='start'?1100:Math.max(650,3200*result.x/level.endX)};raf=requestAnimationFrame(draw);
}
function containsParams(n){return(n.k==='v'&&n.v!=='x')||(n.a&&containsParams(n.a))||(n.b&&containsParams(n.b))||(n.args&&n.args.some(containsParams))}
function selectLevel(l){cancelRun();if(mode==='challenge')drafts[level.id]=$('expression').value;level=l;attempts=0;previous=null;hintStep=0;mode='challenge';$('expression').value=drafts[l.id]||'';updateMode();$('catalogDialog').close();$('expression').focus({preventScroll:true})}
function mapDescription(){return level.id==='salto'?'Pasá por encima del muro y aterrizá del otro lado.':level.id==='valle'?'Buscá un camino por debajo del techo.':level.id==='eco'?'Dos oscilaciones, cuatro pasos estrechos.':level.id==='libre'?'Construí tu propio desvío. Cualquier función continua que resuelva el mapa vale.':'Conectá los extremos, esquivá los obstáculos y buscá las monedas.'}
function updateMode(){const sand=mode==='sandbox';document.body.classList.toggle('sandbox',sand);$('challengeTab').classList.toggle('active',!sand);$('sandboxTab').classList.toggle('active',sand);$('challengeTab').setAttribute('aria-pressed',String(!sand));$('sandboxTab').setAttribute('aria-pressed',String(sand));['mission','hintSection','lesson','ghostControl','catalogButton'].forEach(id=>$(id).hidden=sand);['parameters','sandboxExamples','axesControl'].forEach(id=>$(id).hidden=!sand);$('tryButton').innerHTML=sand?'Recorrer <span>▷</span>':'TRY <span>▷</span>';$('resultBadge').hidden=true;$('mapCaption').hidden=false;$('mapCaption').textContent=sand?'Cambiá la expresión. Mirá qué pasa.':'Imaginá el recorrido. Después, probalo.';$('eyebrow').textContent=sand?'EXPLORACIÓN LIBRE':`DESAFÍO ${String(level.index+1).padStart(2,'0')} / 12`;
 $('levelTitle').replaceChildren(document.createTextNode(sand?'Tu laboratorio de curvas':level.name));if(!sand){let tag=document.createElement('span');tag.className='difficulty';tag.dataset.difficulty=level.difficulty;tag.textContent=level.difficulty;$('levelTitle').append(tag)}
 $('visibilityLabel').textContent=sand?'La curva cambia en vivo':'La nueva curva está oculta hasta TRY';$('attemptLabel').textContent=sand?'EN VIVO':'INTENTO '+String(attempts).padStart(2,'0');$('startCoord').textContent=`(0, ${fmt(level.start.y)})`;$('endCoord').textContent=`(${fmt(level.endX)}, ${fmt(level.end.y)})`;$('missionText').textContent=mapDescription();$('hintContent').hidden=true;$('exploreButton').hidden=true;$('hintButton').innerHTML='<span>✧</span> Una pequeña ayuda <span>+</span>';$('footerNote').textContent=sand?'Experimentá. Compará. Volvé a desafiarte.':'Todos los desafíos están abiertos.';
 $('mapData').replaceChildren();let p=document.createElement('p');p.textContent='Monedas: '+level.coins.map(c=>`(${fmt(c.x)}, ${fmt(c.y)})`).join(' · ');$('mapData').append(p);level.obstacles.forEach(o=>{let p=document.createElement('p');p.textContent=`Obstáculo: x entre ${fmt(o.x)} y ${fmt(o.x+o.w)}; y entre ${fmt(o.y)} y ${fmt(o.y+o.h)}.`;$('mapData').append(p)});
 if(sand){setWorld();updateSandbox()}else{world={xmin:-1.1,xmax:11.1,ymin:-2,ymax:9.4};setFeedback('Conectá la salida con la llegada. Las monedas son el desafío extra.')}render();
}
function changeMode(next){if(mode===next)return;cancelRun();if(mode==='challenge'){drafts[level.id]=$('expression').value;mode=next;$('expression').value=sandboxDraft}else{sandboxDraft=$('expression').value;mode=next;$('expression').value=drafts[level.id]||''}updateMode()}
function updateSandbox(){cancelRun();try{compiled=compile($('expression').value);setFeedback('La curva se actualiza en vivo. Podés usar a, h y k, o escribir directamente los números.')}catch(e){compiled=null;setFeedback(e.message,'error')}render()}
function setWorld(){world=$('viewRange').value==='center'?{xmin:-6,xmax:6,ymin:-6,ymax:6}:$('viewRange').value==='wide'?{xmin:-12,xmax:12,ymin:-12,ymax:12}:{xmin:-1.1,xmax:11.1,ymin:-2,ymax:9.4}}
function catalog(){ $('filters').replaceChildren();['Todos','Fácil','Media','Difícil','Experta'].forEach(f=>{let b=document.createElement('button');b.textContent=f;b.className=filter===f?'active':'';b.onclick=()=>{filter=f;catalog()};$('filters').append(b)});$('levelGrid').replaceChildren();levels.filter(l=>filter==='Todos'||l.difficulty===filter).forEach(l=>{let b=document.createElement('button');b.className='level-card'+(l.id===level.id?' selected':'');let status=progress[l.id];b.innerHTML=`<div class="level-number"><span>${String(l.index+1).padStart(2,'0')}</span><span>${status?'✓ '+status.coins+'/'+l.coins.length+' monedas':'ABIERTO'}</span></div><h3>${l.name}</h3><small>${l.family}</small><span class="difficulty" data-difficulty="${l.difficulty}">${l.difficulty}</span>`;b.onclick=()=>selectLevel(l);$('levelGrid').append(b)});}
$('functionForm').addEventListener('submit',startTry);$('expression').addEventListener('input',()=>{if(mode==='sandbox')updateSandbox();else{$('visibilityLabel').textContent=previous?'Último intento: '+previous.expression:'La nueva curva está oculta hasta TRY';$('resultBadge').hidden=true;setFeedback('Nueva expresión oculta. Tocá TRY para ver su trayectoria.')}});
$('challengeTab').onclick=()=>changeMode('challenge');$('sandboxTab').onclick=()=>changeMode('sandbox');$('catalogButton').onclick=()=>{catalog();$('catalogDialog').showModal()};$('helpButton').onclick=()=>$('helpDialog').showModal();$('syntaxButton').onclick=()=>$('syntaxDialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('ghost').onchange=render;$('axesOnly').onchange=render;$('viewRange').onchange=()=>{cancelRun();setWorld();render()};
$('hintButton').onclick=()=>{hintStep=Math.min(2,hintStep+1);$('hintContent').hidden=false;$('hintContent').replaceChildren();const s=document.createElement('strong');s.textContent=level.family;$('hintContent').append(s,document.createTextNode(hintStep===1?level.hint:level.hint+' '+level.explain));$('hintButton').innerHTML=hintStep===1?'<span>✧</span> Entender la función <span>+</span>':'<span>✧</span> Pista completa <span>✓</span>';$('exploreButton').hidden=false};
$('exploreButton').onclick=()=>{let index={'Rectas':0,'Cuadráticas':1,'Valor absoluto':5,'Exponenciales':2,'Logaritmos':6,'Raíces':4,'Trigonométricas':3,'Racionales':7}[level.family]??1;changeMode('sandbox');setExample(index)};
function setExample(i){param={a:1,h:0,k:0};for(const k of ['a','h','k']){$('slider-'+k).value=param[k];$('value-'+k).textContent=param[k]};$('expression').value=examples[i][1];$('exampleExplanation').textContent=examples[i][2];updateSandbox()}
['a','h','k'].forEach((k,i)=>{const div=document.createElement('div');div.className='parameter';div.innerHTML=`<label class="parameter-top" for="slider-${k}"><span><b>${k}</b> · ${['escala vertical','desplazamiento horizontal','desplazamiento vertical'][i]}</span><b id="value-${k}">${param[k]}</b></label><input type="range" id="slider-${k}" min="-5" max="5" step="0.1" value="${param[k]}">`;$('sliders').append(div);$('slider-'+k).oninput=e=>{param[k]=+e.target.value;$('value-'+k).textContent=fmt(param[k]);updateSandbox()}});
examples.forEach((ex,i)=>{const b=document.createElement('button');b.textContent=ex[0];b.onclick=()=>setExample(i);$('exampleButtons').append(b)});$('exampleExplanation').textContent=examples[1][2];
function renderComparisons(){$('comparisons').replaceChildren();comparisons.forEach((c,i)=>{let row=document.createElement('div');row.className='comparison';row.style.color=c.color;let span=document.createElement('span');span.textContent=c.label;let b=document.createElement('button');b.textContent='×';b.setAttribute('aria-label','Quitar curva '+(i+1));b.onclick=()=>{comparisons.splice(i,1);renderComparisons();render()};row.append(span,b);$('comparisons').append(row)});$('compareButton').disabled=comparisons.length>=3}
$('compareButton').onclick=()=>{if(!compiled){setFeedback('Primero escribí una función válida.','error');return}if(comparisons.length>=3)return;const palette=['#ffc875','#bc9df5','#ed9cac'];comparisons.push({fn:compiled.fn,params:{...param},label:$('expression').value+(/\b[ahk]\b/.test($('expression').value)?` · a=${fmt(param.a)}, h=${fmt(param.h)}, k=${fmt(param.k)}`:''),color:palette.find(c=>!comparisons.some(p=>p.color===c))});renderComparisons();render()};
canvas.addEventListener('pointermove',e=>{const rect=canvas.getBoundingClientRect();hover={x:e.clientX-rect.left,y:e.clientY-rect.top};let x=unpx(hover.x),y=unpy(hover.y);$('coordinateReadout').textContent=`x: ${fmt(x)} · y: ${fmt(y)}`;render()});canvas.addEventListener('pointerleave',()=>{hover=null;render()});
updateMode();
